INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q6','nism-5a-z24','Stamp duty at 0.005% on issue of units applies to an investment of ₹35,00,000. The stamp duty is:','["₹525.00","₹17,500.00","₹175.00","₹1,750.00"]',2,'₹3500000 × 0.005% = ₹175.00.',6) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q7','nism-5a-z24','A Liquid fund invests in debt and money market securities with maturity up to:','["30 days","180 days","91 days","1 year"]',2,'Liquid = up to 91 days.',7) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q8','nism-5a-z24','With NAV of ₹11 and exit load of 1%, the repurchase price is:','["₹10.00","₹11.00","₹10.89","₹11.11"]',2,'11 × (1 − 0.01) = ₹10.89.',8) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q9','nism-5a-z24','An investor invests ₹1,94,000 in an open-ended scheme at an NAV of ₹30.00. With no entry load, the number of units allotted is:','["6324.368","19400.000","6466.667","5820000.000"]',2,'Units = 194000 ÷ 30.00 = 6466.667.',9) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q10','nism-5a-z24','A SIP Top-up of +10% a year on ₹2,500 gives an instalment in year 2 of:','["₹2,750","₹2,510","₹2,600","₹3,000"]',0,'2,500 × 1.10 = 2,750.',10) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q11','nism-5a-z24','A nominee CANNOT be:','["An NRI","A body corporate or a Karta of an HUF","A Central Government","A minor with a guardian"]',1,'Trusts (other than religious or charitable), societies and partnerships are also barred.',11) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q12','nism-5a-z24','In finance theory, which risk is rewarded with a higher expected return?','["Strike-related risk","Unsystematic risk","Systematic risk","Company labour risk"]',2,'Unsystematic risk is not rewarded.',12) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q13','nism-5a-z24','For equity and debt schemes (excluding liquid and overnight), the cut-off time for purchases is:','["4:00 pm","1:30 pm","2:00 pm","3:00 pm"]',3,'Funds must be available for utilisation before the cut-off.',13) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q14','nism-5a-z24','A Consolidated Account Statement (CAS) is sent monthly to investors:','["Only to NRIs","Only on request","Who had a transaction that month","Only if the portfolio loss exceeds 10%"]',2,'Half-yearly if no transaction in the preceding 6 months.',14) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q15','nism-5a-z24','A fund returned 20% with a standard deviation of 15%. The risk-free rate is 7%. The Sharpe ratio is:','["1.33","0.76","0.87","1.80"]',2,'Sharpe = (20 − 7) ÷ 15.',15) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q16','nism-5a-z24','Mutual fund industry AUM reached ₹79.46 lakh crore in March 2026, having been ₹12.33 lakh crore in March 2016. The CAGR is about:','["30%","8%","12%","20.48%"]',3,'As per the workbook growth data.',16) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q17','nism-5a-z24','A goal costs ₹89,000 today. With inflation of 6% p.a., its cost after 11 years will be approximately:','["₹1,47,740","₹1,68,949","₹1,79,085","₹1,59,385"]',1,'FV = 89000 × (1 + 6%)^11.',17) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q18','nism-5a-z24','Where a TRI is unavailable for a period, the benchmark return is shown using:','["No benchmark","The risk-free rate","A composite CAGR: PRI until TRI starts and TRI thereafter","The AMC''s own estimate"]',2,'This was permitted for older periods.',18) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q19','nism-5a-z24','For a breach of the AMFI code, AMFI first seeks an explanation from the intermediary within:','["3 weeks","1 year","3 days","3 months"]',0,'A proven second violation leads to ARN cancellation.',19) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q20','nism-5a-z24','With a scheme return of 8%, risk-free 5% and beta 1.2, the Treynor ratio is:','["2.5","0.6","1.5","3.0"]',0,'(8 − 5) ÷ 1.2 = 2.5.',20) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z24-q21','nism-5a-z24','A Power of Attorney holder can do everything for the investor EXCEPT:','["Switch schemes","Redeem units","Make additional purchases","Make or change nominations"]',3,'Nominations cannot be made through a PoA.',21) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
