INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z28-q24','nism-5a-z28','Under SEBI categorisation, a Large Cap is defined as companies ranked:','["1st to 50th","1st to 250th","1st to 100th by full market capitalisation","101st to 250th"]',2,'Large 1–100; Mid 101–250; Small 251 onwards.',24) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z28-q25','nism-5a-z28','Where a TRI is unavailable for a period, the benchmark return is shown using:','["A composite CAGR: PRI until TRI starts and TRI thereafter","No benchmark","The AMC''s own estimate","The risk-free rate"]',0,'This was permitted for older periods.',25) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z28-q26','nism-5a-z28','An investor extrapolating the recent bull-market performance into the future is showing:','["Loss aversion","Availability of liquidity","Confirmation bias","Recency bias"]',3,'Recency bias is extrapolating recent events.',26) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z28-q27','nism-5a-z28','A scheme with average net assets of ₹4100 crore incurs total recurring expenses of ₹1.80 crore in a year. Its expense ratio is:','["0.044%","0.022%","0.066%","0.088%"]',0,'TER = 1.80 ÷ 4100 × 100 = 0.044%.',27) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z28-q28','nism-5a-z28','A SIP Top-up of +10% a year on ₹2,500 gives an instalment in year 2 of:','["₹2,750","₹3,000","₹2,510","₹2,600"]',0,'2,500 × 1.10 = 2,750.',28) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
